package ch.bbw.zork;/** * Class Command - Part of the "Zork" game. *  * author: Michael Kolling version: 1.0 date: July 1999 * refactoring: Rinaldo Lanza, September 2020 */public abstract class Command {	private String commandWord;	private String summary;	private String helpText;	private String exampleString;	private int time;	public Command(String commandWord, int time) {		this(commandWord, time, "", "", "");	}	public Command(String commandWord, int time, String summary, String helpText) {		this(commandWord, time, summary, helpText, "");	}	public Command(String commandWord, int time, String summary, String helpText, String exampleString) {		this.commandWord = commandWord;		this.summary = summary;		this.time = time;		this.exampleString = exampleString;	}	public String getCommandWord() {		return commandWord;	}	public String getSummary() {return summary; }	public int getTime() { return time; }	public String getExampleString() { return exampleString; }	public void setSummary(String summary) {		this.summary = summary;	}	public void setHelpText(String helpText) {		this.helpText = helpText;	}	public void setExampleString(String exampleString) {		this.exampleString = exampleString;	}	@Override	public String toString() {		String result = String.join("\n",				helpText,				"Time loss:\t" + time + " min"		);		if (!exampleString.isEmpty()) {			result = String.join("\n", result, "Example:\t" + exampleString);		}		return String.format("%s%n", result);	}}